import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication
matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Calculate row and column indices for this thread
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    // Only compute if within matrix bounds
    if (row < N && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < N; k++) {
            sum += A[row * N + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Check input dimensions
    int N = A.size(0);
    if (N != A.size(1) || N != B.size(0) || N != B.size(1)) {
        throw std::invalid_argument("Input matrices must be square and of same size");
    }

    // Create output tensor
    auto C = torch::zeros({N, N}, A.options());

    // Configure kernel launch parameters
    const int block_size = 16;  // 16x16 = 256 threads per block
    dim3 threads(block_size, block_size);
    dim3 blocks((N + block_size - 1) / block_size, (N + block_size - 1) / block_size);

    // Launch kernel
    matmul_kernel<<<blocks, threads>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

