matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Define tile size
    const int TILE_SIZE = 16;

    // Shared memory for tiles of A and B
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Calculate global row and column indices
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    // Initialize the accumulator
    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Calculate indices within the tile
        int tRow = threadIdx.y;
        int tCol = threadIdx.x;

        // Load tile of A into shared memory
        int A_col = t * TILE_SIZE + tCol;
        if (row < N && A_col < N) {
            As[tRow][tCol] = A[row * N + A_col];
        } else {
            As[tRow][tCol] = 0.0f;
        }

        // Load tile of B into shared memory
        int B_row = t * TILE_SIZE + tRow;
        if (B_row < N && col < N) {
            Bs[tRow][tCol] = B[B_row * N + col];
        } else {
            Bs[tRow][tCol] = 0.0f;
        }

        // Synchronize to ensure all threads have loaded their tiles
        __syncthreads();

        // Compute partial dot product for this tile
        for (int k = 0; k < TILE_SIZE; k++) {
            sum += As[tRow][k] * Bs[k][tCol];
        }

        // Synchronize before loading next tiles
        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

