import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the optimized CUDA kernel with double buffering and prefetching
matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Define larger tile size
    const int TILE_SIZE = 32;

    // Double buffering: two sets of shared memory tiles
    __shared__ float As[2][TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[2][TILE_SIZE][TILE_SIZE];

    // Calculate global row and column indices
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    // Initialize the accumulator
    float sum = 0.0f;

    // Buffer index for double buffering
    int buf_idx = 0;

    // Prefetch the first tile
    int tRow = threadIdx.y;
    int tCol = threadIdx.x;

    int A_col = 0 * TILE_SIZE + tCol;
    if (row < N && A_col < N) {
        As[buf_idx][tRow][tCol] = A[row * N + A_col];
    } else {
        As[buf_idx][tRow][tCol] = 0.0f;
    }

    int B_row = 0 * TILE_SIZE + tRow;
    if (B_row < N && col < N) {
        Bs[buf_idx][tRow][tCol] = B[B_row * N + col];
    } else {
        Bs[buf_idx][tRow][tCol] = 0.0f;
    }

    __syncthreads();

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Prefetch next tile
        int next_t = t + 1;
        if (next_t < (N + TILE_SIZE - 1) / TILE_SIZE) {
            int next_buf_idx = 1 - buf_idx;

            int next_A_col = next_t * TILE_SIZE + tCol;
            if (row < N && next_A_col < N) {
                As[next_buf_idx][tRow][tCol] = A[row * N + next_A_col];
            } else {
                As[next_buf_idx][tRow][tCol] = 0.0f;
            }

            int next_B_row = next_t * TILE_SIZE + tRow;
            if (next_B_row < N && col < N) {
                Bs[next_buf_idx][tRow][tCol] = B[next_B_row * N + col];
            } else {
                Bs[next_buf_idx][tRow][tCol] = 0.0f;
            }
        }

        // Compute partial dot product for current tile with loop unrolling
        for (int k = 0; k < TILE_SIZE; k += UNROLL_FACTOR) {
            sum += As[buf_idx][tRow][k] * Bs[buf_idx][k][tCol];
            sum += As[buf_idx][tRow][k+1] * Bs[buf_idx][k+1][tCol];
            sum += As[buf_idx][tRow][k+2] * Bs[buf_idx][k+2][tCol];
            sum += As[buf_idx][tRow][k+3] * Bs[buf_idx][k+3][tCol];
        }

        // Swap buffers
        buf_idx = 1 - buf_idx;

        // Synchronize before loading next tiles
        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Check input dimensions
    int N = A.size(0);
    if (N != A.size(1) || N != B.size(0) || N != B.size(1)) {
